import sys

def main():
    vals = list(map(int, sys.stdin.read().split()))
    unknown = [i for i, x in enumerate(vals) if x == -1]

    limits = [
        (1, 100),   # J
        (0, 300),   # P
        (0, 100),   # V
        (0, 100),   # E
        (0, 100),   # D
    ]

    ans = None

    if len(unknown) == 1:
        i = unknown[0]
        for x in range(limits[i][0], limits[i][1] + 1):
            cand = vals[:]
            cand[i] = x
            if cand[0] == cand[2] + cand[3] + cand[4] and cand[1] == 3 * cand[2] + cand[3]:
                ans = cand
                break
    else:
        i, j = unknown
        for x in range(limits[i][0], limits[i][1] + 1):
            for y in range(limits[j][0], limits[j][1] + 1):
                cand = vals[:]
                cand[i] = x
                cand[j] = y
                if cand[0] == cand[2] + cand[3] + cand[4] and cand[1] == 3 * cand[2] + cand[3]:
                    ans = cand
                    break
            if ans is not None:
                break

    print(*ans)

if __name__ == "__main__":
    main()
